t.script:

(function () {
    const overlay = document.getElementById('caPdfOverlay');
    const cookieName = 'courier_pdf_download_token';
    let isPdfLocked = false;
    let activeToken = '';
    let pollTimer = null;
    let fallbackTimer = null;

    const getCookie = function (name) {
        return document.cookie.split(';').map(function (part) {
            return part.trim();
        }).find(function (part) {
            return part.indexOf(name + '=') === 0;
        }) || '';
    };

    const clearDownloadCookie = function () {
        document.cookie = cookieName + '=; Max-Age=0; path=/';
    };

    const unlockPdf = function () {
        isPdfLocked = false;
        activeToken = '';
        if (pollTimer) window.clearInterval(pollTimer);
        if (fallbackTimer) window.clearTimeout(fallbackTimer);
        pollTimer = null;
        fallbackTimer = null;
        if (overlay) {
            overlay.classList.remove('is-open');
            overlay.setAttribute('aria-hidden', 'true');
        }
        document.querySelectorAll('.ca-pdf-download').forEach(function (link) {
            link.classList.remove('is-loading');
            link.removeAttribute('aria-disabled');
            if (link.dataset.originalHtml) {
                link.innerHTML = link.dataset.originalHtml;
            }
        });
    };

    document.addEventListener('click', function (event) {
        const link = event.target.closest('.ca-pdf-download');
        if (!link) return;
        if (isPdfLocked) {
            event.preventDefault();
            event.stopPropagation();
            return;
        }

        isPdfLocked = true;
        activeToken = String(Date.now()) + '-' + Math.random().toString(36).slice(2);
        clearDownloadCookie();

        document.querySelectorAll('.ca-pdf-download').forEach(function (pdfLink) {
            if (!pdfLink.dataset.originalHtml) {
                pdfLink.dataset.originalHtml = pdfLink.innerHTML;
            }
            pdfLink.setAttribute('aria-disabled', 'true');
        });
        link.classList.add('is-loading');
        link.innerHTML = '<span class="ca-spinner"></span>Hazırlanıyor';
        if (overlay) {
            overlay.classList.add('is-open');
            overlay.setAttribute('aria-hidden', 'false');
        }

        const url = new URL(link.href, window.location.origin);
        url.searchParams.set('download_token', activeToken);
        link.href = url.toString();

        pollTimer = window.setInterval(function () {
            const cookie = getCookie(cookieName);
            if (cookie && decodeURIComponent(cookie.split('=').slice(1).join('=')) === activeToken) {
                clearDownloadCookie();
                unlockPdf();
            }
        }, 500);
        fallbackTimer = window.setTimeout(unlockPdf, 120000);
    }, true);

    window.addEventListener('pageshow', function () {
        if (isPdfLocked) unlockPdf();
    });
})();

section.script:
(function () {
    const key = 'partner_courier_accounting_login';
    const form = document.querySelector('.ca-login-card form');
    const courierInput = document.getElementById('ca_login_courier_id');
    const identityInput = document.getElementById('ca_login_identity_no');
    const rememberInput = document.getElementById('ca_login_remember');
    const privacyGroup = document.getElementById('ca_login_privacy_group');
    const privacyInput = document.getElementById('ca_login_privacy_kvkk');
    const policyOpen = document.getElementById('ca_policy_open');
    const policyClose = document.getElementById('ca_policy_close');
    const policyModal = document.getElementById('ca_policy_modal');
    if (!form || !courierInput || !identityInput || !rememberInput) return;
    const privacyKey = 'partner_courier_accounting_privacy_accepted_courier_ids';
    let privacyAcceptedCourierIds = [];
    try {
        privacyAcceptedCourierIds = JSON.parse(window.localStorage.getItem(privacyKey) || '[]');
        if (!Array.isArray(privacyAcceptedCourierIds)) privacyAcceptedCourierIds = [];
    } catch (error) {}
    const togglePrivacyInput = function () {
        const courierId = (courierInput.value || '').trim();
        const isAccepted = courierId && privacyAcceptedCourierIds.includes(courierId);
        if (privacyGroup) privacyGroup.style.display = isAccepted ? 'none' : 'flex';
        if (privacyInput && isAccepted) privacyInput.checked = false;
    };
    try {
        const saved = JSON.parse(window.localStorage.getItem(key) || '{}');
        if (saved.courier_id || saved.identity_no) {
            courierInput.value = saved.courier_id || '';
            identityInput.value = saved.identity_no || '';
            rememberInput.checked = true;
        }
    } catch (error) {}
    togglePrivacyInput();
    courierInput.addEventListener('input', togglePrivacyInput);
    if (policyOpen && policyModal) {
        policyOpen.addEventListener('click', function () {
            policyModal.classList.add('is-open');
        });
    }
    if (policyClose && policyModal) {
        policyClose.addEventListener('click', function () {
            policyModal.classList.remove('is-open');
        });
    }
    if (policyModal) {
        policyModal.addEventListener('click', function (event) {
            if (event.target === policyModal) policyModal.classList.remove('is-open');
        });
    }
    form.addEventListener('submit', function () {
        if (rememberInput.checked) {
            window.localStorage.setItem(key, JSON.stringify({
                courier_id: courierInput.value || '',
                identity_no: identityInput.value || ''
            }));
        } else {
            window.localStorage.removeItem(key);
        }
    });
})();

t.script:
(function () {
    const phoneLink = document.getElementById('ca_emergency_phone');
    const phoneModal = document.getElementById('ca_emergency_phone_modal');
    const phoneClose = document.getElementById('ca_emergency_phone_close');
    const phoneTitle = document.getElementById('ca_emergency_phone_title');
    const phoneMessage = document.getElementById('ca_emergency_phone_message');
    const phoneNumber = '+905445752833';
    const fallbackDevice = /(Xiaomi|Redmi|POCO|vivo|TECNO|\bMi (?:[A-Z]|\d))/i.test(navigator.userAgent || '');
    if (!phoneLink || !phoneModal || !fallbackDevice) return;

    const showModal = function (copied) {
        if (phoneTitle) phoneTitle.textContent = copied ? 'Numara kopyalandı' : 'Numarayı manuel arayın';
        if (phoneMessage) {
            phoneMessage.textContent = copied
                ? 'Telefon uygulamanızı açıp numarayı yapıştırarak arayabilirsiniz.'
                : 'Telefon uygulamanızı açıp bu numarayı girerek arayabilirsiniz.';
        }
        phoneModal.classList.add('is-open');
    };
    const copyPhoneNumber = async function () {
        try {
            if (navigator.clipboard && window.isSecureContext) {
                await navigator.clipboard.writeText(phoneNumber);
                return true;
            }
        } catch (error) {}
        const input = document.createElement('textarea');
        input.value = phoneNumber;
        input.setAttribute('readonly', '');
        input.style.cssText = 'position:fixed; opacity:0; pointer-events:none;';
        document.body.appendChild(input);
        input.select();
        const copied = document.execCommand('copy');
        input.remove();
        return copied;
    };

    phoneLink.addEventListener('click', async function (event) {
        event.preventDefault();
        showModal(await copyPhoneNumber());
    });
    phoneClose.addEventListener('click', function () {
        phoneModal.classList.remove('is-open');
    });
    phoneModal.addEventListener('click', function (event) {
        if (event.target === phoneModal) phoneModal.classList.remove('is-open');
    });
})();

section.script:
(function () {
    const homeCard = document.querySelector('.ca-home-card');
    const contactId = homeCard ? parseInt(homeCard.dataset.contactId, 10) : 0;
    const userId = homeCard ? parseInt(homeCard.dataset.userId, 10) : 0;
    const courierId = homeCard ? (homeCard.dataset.courierId || '').trim() : '';
    if (courierId && homeCard.dataset.privacyAccepted === '1') {
        const privacyKey = 'partner_courier_accounting_privacy_accepted_courier_ids';
        let acceptedCourierIds = [];
        try {
            acceptedCourierIds = JSON.parse(window.localStorage.getItem(privacyKey) || '[]');
            if (!Array.isArray(acceptedCourierIds)) acceptedCourierIds = [];
        } catch (error) {}
        if (!acceptedCourierIds.includes(courierId)) {
            acceptedCourierIds.push(courierId);
            window.localStorage.setItem(privacyKey, JSON.stringify(acceptedCourierIds));
        }
    }
    if (!contactId || !window.ReactNativeWebView) return;
    window.ReactNativeWebView.postMessage(JSON.stringify({
        type: 'USER_LOGGED_IN',
        userId: userId || false,
        contactId: contactId
    }));
})();

t.script:
(function () {
    document.querySelectorAll('.ca-call-button').forEach((button) => {
        button.addEventListener('click', function (event) {
            const phoneUrl = button.dataset.phoneUrl || button.getAttribute('href');
            if (!phoneUrl) return;
            event.preventDefault();
            window.location.href = phoneUrl;
        });
    });
})();

(function () {
    const modal = document.getElementById('caInfoModal');
    const title = document.getElementById('caInfoTitle');
    const text = document.getElementById('caInfoText');
    if (!modal || !title || !text) return;
    const close = () => {
        modal.classList.remove('is-open');
        modal.setAttribute('aria-hidden', 'true');
    };
    document.querySelectorAll('.ca-info-btn').forEach((button) => {
        button.addEventListener('click', () => {
            title.textContent = button.dataset.title || '';
            text.textContent = button.dataset.info || '';
            modal.classList.add('is-open');
            modal.setAttribute('aria-hidden', 'false');
        });
    });
    modal.querySelector('.ca-modal-close').addEventListener('click', close);
    modal.addEventListener('click', (event) => {
        if (event.target === modal) close();
    });
    document.addEventListener('keydown', (event) => {
        if (event.key === 'Escape') close();
    });
})();

(function () {
    const forms = document.querySelectorAll('.ca-upload-form');
    forms.forEach((form) => {
        form.addEventListener('submit', function (e) {
            const btn = form.querySelector('.ca-upload-btn');
            if (btn) {
                btn.disabled = true;
                btn.replaceChildren();
                const spinner = document.createElement('span');
                spinner.className = 'ca-spinner';
                btn.appendChild(spinner);
                const text = document.createTextNode(' Yükleniyor...');
                btn.appendChild(text);
            }
        });
    });
})();


(function () {
    const button = document.getElementById('caRateAppButton');
    if (!button) {
        return;
    }
    const userAgent = navigator.userAgent || '';
    const isIPadOS = navigator.platform === 'MacIntel'
        && navigator.maxTouchPoints > 1;
    const isAppleMobile = /iPhone|iPad|iPod/i.test(userAgent)
        || isIPadOS;
    button.href = isAppleMobile
        ? button.dataset.iosUrl
        : button.dataset.androidUrl;
})();

(function () {
    const form = document.querySelector('.ca-request-form');
    const typeSelect = form ? form.querySelector('.ca-request-type-select') : null;
    const amountField = form ? form.querySelector('.ca-request-amount-field') : null;
    const amountInput = amountField ? amountField.querySelector('input') : null;

    const toggleAmountField = function () {
        if (!typeSelect || !amountField || !amountInput) return;
        const isAdvance = typeSelect.value === 'advance';
        amountField.style.display = isAdvance ? 'grid' : 'none';
        amountInput.required = isAdvance;
        if (!isAdvance) amountInput.value = '';
    };

    if (typeSelect) {
        typeSelect.addEventListener('change', toggleAmountField);
        toggleAmountField();
    }

    if (form) {
        form.addEventListener('submit', function () {
            const btn = form.querySelector('.ca-submit-btn');
            if (btn) {
                btn.disabled = true;
                btn.replaceChildren();
                const spinner = document.createElement('span');
                spinner.className = 'ca-spinner';
                btn.appendChild(spinner);
                const text = document.createTextNode(' Gönderiliyor...');
                btn.appendChild(text);
            }
        });
    }
})();
